import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"询问当前时间","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/dialogues/04-asking-the-time.md","filePath":"zh/more/maltese/practice/dialogues/04-asking-the-time.md"}'),e={name:"zh/more/maltese/practice/dialogues/04-asking-the-time.md"},n=r('<h1 id="询问当前时间" tabindex="-1">询问当前时间 <a class="header-anchor" href="#询问当前时间" aria-label="Permalink to &quot;询问当前时间&quot;">​</a></h1><p><strong>场景：</strong> 两位朋友在约好的地点碰面，一人询问时间并确认是否迟到。</p><h2 id="完整对话" tabindex="-1">完整对话 <a class="header-anchor" href="#完整对话" aria-label="Permalink to &quot;完整对话&quot;">​</a></h2><p><strong>Mark：</strong> Skużani, x&#39;ħin hu issa?</p><p><strong>Lina：</strong> Huma t-tmienja u kwart.</p><p><strong>Mark：</strong> Grazzi. Għandi appuntament fit-tmienja u nofs.</p><p><strong>Lina：</strong> Għad għandek ħmistax-il minuta.</p><p><strong>Mark：</strong> Tajjeb. Il-post jinsab ħdejn il-pjazza, hux?</p><p><strong>Lina：</strong> Iva, eżattament. Jien qiegħda quddiem il-bieb.</p><p><strong>Mark：</strong> Qed nitlaq issa. Nasal f&#39;għaxar minuti.</p><p><strong>Lina：</strong> Sewwa, narak dalwaqt.</p><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><h3 id="_1-mark" tabindex="-1">1. Mark <a class="header-anchor" href="#_1-mark" aria-label="Permalink to &quot;1. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Skużani, x&#39;ħin hu issa?</p><p><strong>整句：</strong> 不好意思，现在几点了？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Skużani</td><td>不好意思；请原谅我</td><td>礼貌用语</td></tr><tr><td>x&#39;ħin</td><td>几点；什么时间</td><td><code>x&#39;</code>“什么” + <code>ħin</code>“时间”</td></tr><tr><td>hu</td><td>是</td><td>第三人称阳性代词；此处对应“时间”</td></tr><tr><td>issa</td><td>现在</td><td>时间副词</td></tr></tbody></table><h3 id="_2-lina" tabindex="-1">2. Lina <a class="header-anchor" href="#_2-lina" aria-label="Permalink to &quot;2. Lina&quot;">​</a></h3><p><strong>Malti:</strong> Huma t-tmienja u kwart.</p><p><strong>整句：</strong> 现在是八点一刻。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Huma</td><td>它们是；他们是</td><td>此处作系词形式引出时间</td></tr><tr><td>it-tmienja</td><td>八点</td><td>带定冠词的钟点形式</td></tr><tr><td>u</td><td>和；过</td><td>连接整点与分钟</td></tr><tr><td>kwart</td><td>一刻钟</td><td>时间名词，十五分钟</td></tr></tbody></table><h3 id="_3-mark" tabindex="-1">3. Mark <a class="header-anchor" href="#_3-mark" aria-label="Permalink to &quot;3. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi. Għandi appuntament fit-tmienja u nofs.</p><p><strong>整句：</strong> 谢谢。我八点半有约。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌表达</td></tr><tr><td>Għandi</td><td>我有</td><td><code>għand</code> 的第一人称单数形式</td></tr><tr><td>appuntament</td><td>预约；约会</td><td>阳性名词</td></tr><tr><td>fit-tmienja</td><td>在八点</td><td><code>f&#39;</code>“在” + 钟点形式缩合</td></tr><tr><td>u</td><td>和；过</td><td>连接时间部分</td></tr><tr><td>nofs</td><td>半</td><td><code>u nofs</code> 表示半点</td></tr></tbody></table><h3 id="_4-lina" tabindex="-1">4. Lina <a class="header-anchor" href="#_4-lina" aria-label="Permalink to &quot;4. Lina&quot;">​</a></h3><p><strong>Malti:</strong> Għad għandek ħmistax-il minuta.</p><p><strong>整句：</strong> 你还有十五分钟。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għad</td><td>仍然；还</td><td>表示状态持续</td></tr><tr><td>għandek</td><td>你有</td><td><code>għand</code> 的第二人称单数形式</td></tr><tr><td>ħmistax-il</td><td>十五</td><td>数字与后接名词的连接形式</td></tr><tr><td>minuta</td><td>分钟</td><td>阴性名词</td></tr></tbody></table><h3 id="_5-mark" tabindex="-1">5. Mark <a class="header-anchor" href="#_5-mark" aria-label="Permalink to &quot;5. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb. Il-post jinsab ħdejn il-pjazza, hux?</p><p><strong>整句：</strong> 好的。地点在广场旁边，对吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tajjeb</td><td>好；好的</td><td>阳性形式，也可作回应</td></tr><tr><td>il-post</td><td>地点；地方</td><td><code>il-</code> 定冠词 + <code>post</code></td></tr><tr><td>jinsab</td><td>位于；在</td><td>第三人称阳性单数形式</td></tr><tr><td>ħdejn</td><td>在……旁边</td><td>位置介词</td></tr><tr><td>il-pjazza</td><td>广场</td><td>阴性名词，带定冠词</td></tr><tr><td>hux</td><td>是吗；对吗</td><td>句末确认用语</td></tr></tbody></table><h3 id="_6-lina" tabindex="-1">6. Lina <a class="header-anchor" href="#_6-lina" aria-label="Permalink to &quot;6. Lina&quot;">​</a></h3><p><strong>Malti:</strong> Iva, eżattament. Jien qiegħda quddiem il-bieb.</p><p><strong>整句：</strong> 对，正是如此。我在门前。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Iva</td><td>是；对</td><td>肯定回答</td></tr><tr><td>eżattament</td><td>正是；准确地</td><td>副词</td></tr><tr><td>Jien</td><td>我</td><td>强调代词</td></tr><tr><td>qiegħda</td><td>位于；在</td><td>阴性说话者形式；男性说话者用 <code>qiegħed</code></td></tr><tr><td>quddiem</td><td>在……前面</td><td>位置介词</td></tr><tr><td>il-bieb</td><td>门</td><td>阳性名词，带定冠词</td></tr></tbody></table><h3 id="_7-mark" tabindex="-1">7. Mark <a class="header-anchor" href="#_7-mark" aria-label="Permalink to &quot;7. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Qed nitlaq issa. Nasal f&#39;għaxar minuti.</p><p><strong>整句：</strong> 我现在出发。十分钟后到。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Qed</td><td>正在</td><td>与动词一起表示正在进行</td></tr><tr><td>nitlaq</td><td>我离开；我出发</td><td>第一人称单数形式</td></tr><tr><td>issa</td><td>现在</td><td>时间副词</td></tr><tr><td>Nasal</td><td>我到达</td><td>第一人称单数形式</td></tr><tr><td>f&#39;għaxar</td><td>在……之后；用……时间</td><td><code>f&#39;</code> + <code>għaxar</code>“十”</td></tr><tr><td>minuti</td><td>分钟</td><td><code>minuta</code> 的复数</td></tr></tbody></table><h3 id="_8-lina" tabindex="-1">8. Lina <a class="header-anchor" href="#_8-lina" aria-label="Permalink to &quot;8. Lina&quot;">​</a></h3><p><strong>Malti:</strong> Sewwa, narak dalwaqt.</p><p><strong>整句：</strong> 好的，一会儿见。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Sewwa</td><td>好；好的</td><td>常见回应</td></tr><tr><td>narak</td><td>我见到你；再见</td><td><code>nara</code>“我看见” + <code>-k</code>“你”</td></tr><tr><td>dalwaqt</td><td>很快；不久</td><td>时间副词</td></tr></tbody></table><h2 id="时间表达提示" tabindex="-1">时间表达提示 <a class="header-anchor" href="#时间表达提示" aria-label="Permalink to &quot;时间表达提示&quot;">​</a></h2><ul><li><code>u kwart</code>：过一刻；<code>u nofs</code>：过半点。</li><li><code>neqsin kwart</code>：差一刻到下一点，例如 <code>id-disgħa neqsin kwart</code>（差一刻九点，8:45）。</li><li>需要避免歧义时，使用 24 小时制数字时间。</li></ul>',46),o=[n];function i(h,s,l,c,p,g){return d(),a("div",null,o)}const m=t(e,[["render",i]]);export{u as __pageData,m as default};
